func (this *Blofin) HandleOrderBook(client any, message map[string]any) {
	//
	//   {
	//     arg: {
	//         channel: "books",
	//         instId: "DOGE-USDT",
	//     },
	//     action: "snapshot", // can be 'snapshot' or 'update'
	//     data: {
	//         asks: [   [ 0.08096, 1 ], [ 0.08097, 123 ], ...   ],
	//         bids: [   [ 0.08095, 4 ], [ 0.08094, 237 ], ...   ],
	//         ts: "1707491587909",
	//         prevSeqId: "0", // in case of 'update' there will be some value, less then seqId
	//         seqId: "3374250786",
	//     },
	// }
	//
	var arg map[string]any = ccxt.SafeMapTyped(message, "arg")
	var channelName *string = this.SafeString(arg, "channel")
	var data map[string]any = ccxt.SafeMapTyped(message, "data")
	var marketId *string = this.SafeString(arg, "instId")
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	if symbol != nil {
		if _, ok := this.Orderbooks[*symbol]; !ok {
			this.Orderbooks[*symbol] = this.OrderBook()
		}
	}
	var orderbook ccxt.OrderBookInterface
	if symbol != nil {
		orderbook = this.Orderbooks[*symbol].(ccxt.OrderBookInterface)
	}
	var timestamp *int64 = this.SafeInteger(data, "ts")
	var action *string = this.SafeString(message, "action")
	if action != nil && *action == "snapshot" {
		var orderBookSnapshot map[string]any = this.ParseOrderBook(data, symbol, timestamp)
		orderBookSnapshot["nonce"] = this.SafeInteger(data, "seqId")
		orderbook.(ccxt.OrderBookInterface).Reset(orderBookSnapshot)
	} else {
		var asks []any = ccxt.SafeListTypedDefault(data, "asks", []any{})
		var bids []any = ccxt.SafeListTypedDefault(data, "bids", []any{})
		this.HandleDeltasWithKeys(orderbook.GetAsks(), asks)
		this.HandleDeltasWithKeys(orderbook.GetBids(), bids)
		orderbook.SetTimestamp(timestamp)
		orderbook.SetDatetime(this.Iso8601(timestamp))
	}
	if symbol != nil {
		this.Orderbooks[*symbol] = orderbook
	}
	if channelName != nil {
		var messageHash string = *channelName + ":" + *symbol
		client.(ccxt.ClientInterface).Resolve(orderbook, messageHash)
	}
}

