func (this *Blofin) watchOHLCVForSymbolsBody(ch chan ccxt.AsyncResult[map[string]map[string][]ccxt.OHLCV], symbolsAndTimeframes any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	var symbolsLength int = ccxt.GetArrayLength(symbolsAndTimeframes)
	if (symbolsLength == 0) || ccxt.IsEqual(this.SafeList(symbolsAndTimeframes, 0), nil) {
		panic(ccxt.ArgumentsRequired(this.Id + " watchOHLCVForSymbols() requires a an array of symbols and timeframes, like  [['BTC/USDT', '1m'], ['LTC/USDT', '5m']]"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.WatchMultipleWrapperAsync(true, "candle", "watchOHLCVForSymbols", symbolsAndTimeframes, params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	result := r1.Value
	var symbol *string = this.SafeString(result, 0, "")
	var timeframe *string = this.SafeString(result, 1, "")
	var candles any = this.SafeValue(result, 2)
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(candles).GetLimit(symbol, limit)
	}
	var filtered []any = this.FilterBySinceLimit(candles, since, limitResolved, 0, true)

	ch <- ccxt.AsyncResult[map[string]map[string][]ccxt.OHLCV]{Value: ccxt.OHLCVForSymbolsMapFromMap(this.CreateOHLCVObject(symbol, timeframe, filtered))}
	return nil
}

