func (this *Blofin) watchOrdersForSymbolsBody(ch chan ccxt.AsyncResult[[]ccxt.Order], symbols any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params

	r := <-this.AuthenticateAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	if this.Markets() == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var trigger *bool = this.SafeBool2(params, "stop", "trigger")
	var paramsOmitted map[string]any = this.OmitDict(params, []any{"stop", "trigger"})
	var channel string = "orders"
	if trigger != nil && *trigger == true {
		channel = "orders-algo"
	}

	r2 := <-this.WatchMultipleWrapperAsync(false, channel, "watchOrdersForSymbols", symbols, paramsOmitted)
	if r2.Err != nil {
		panic(r2.Err)
	}
	var orders ccxt.ArrayCacheInterface = ccxt.AsArrayCache(r2.Value)
	var first map[string]any = ccxt.SafeMapTyped(orders, 0)
	var tradeSymbol *string = this.SafeString(first, "symbol")
	var limitResolved *int64 = limit
	if this.NewUpdates {
		limitResolved = ccxt.ToGetsLimit(orders).GetLimit(tradeSymbol, limit)
	}

	ch <- ccxt.AsyncResult[[]ccxt.Order]{Value: ccxt.OrdersFromList(this.FilterBySinceLimit(orders, since, limitResolved, "timestamp", true))}
	return nil
}
func (this *Blofin) HandleOrders(client any, message map[string]any) {
	//
	//     {
	//         action: 'update',
	//         arg: { channel: 'orders' },
	//         data: [
	//           <same object as shown in REST example>
	//         ]
	//     }
	//
	if this.Orders == nil {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheBySymbolById(limit)
	}
	var orders any = this.Orders
	var arg map[string]any = ccxt.SafeMapTyped(message, "arg")
	var channelName *string = this.SafeString(arg, "channel")
	var data []any = ccxt.SafeListTyped(message, "data")
	for i := 0; i < len(data); i++ {
		var order map[string]any = this.ParseWsOrder(this.SafeValue(data, i))
		orders.(ccxt.Appender).Append(order)
		if channelName != nil {
			client.(ccxt.ClientInterface).Resolve(orders, *channelName+":"+*this.SafeString(order, "symbol", ""))
		}
		client.(ccxt.ClientInterface).Resolve(orders, channelName)
	}
}
func (this *Blofin) ParseWsOrder(order any, optionalArgs ...any) map[string]any {
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	return ccxt.OrderToMap(this.ParseOrder(order, market))
}

