func (this *Blofin) watchPositionsBody(ch chan ccxt.AsyncResult[[]ccxt.Position], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	symbols := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbols
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	r := <-this.AuthenticateAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	if this.Markets() == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}

	r2 := <-this.WatchMultipleWrapperAsync(false, "positions", "watchPositions", symbols, params)
	if r2.Err != nil {
		panic(r2.Err)
	}
	newPositions := r2.Value
	if this.NewUpdates {

		var resolved []any
		switch resolvedBox := newPositions.(type) {
		case []any:
			resolved = resolvedBox
		case ccxt.IArrayCache:
			resolved = resolvedBox.ToArray()
		case nil:
		default:
			panic(ccxt.ExchangeError("resolved value is not []any"))
		}
		ch <- ccxt.AsyncResult[[]ccxt.Position]{Value: ccxt.PositionsFromList(resolved)}
		return nil
	}

	ch <- ccxt.AsyncResult[[]ccxt.Position]{Value: ccxt.PositionsFromList(this.FilterBySymbolsSinceLimit(this.WsCacheObjGet("Positions"), symbols, since, limit))}
	return nil
}
func (this *Blofin) HandlePositions(client any, message map[string]any) {
	//
	//     {
	//         arg: { channel: 'positions' },
	//         data: [
	//           <same object as shown in REST example>
	//         ]
	//     }
	//
	if this.Positions == nil {
		this.Positions = ccxt.NewArrayCacheBySymbolBySide()
	}
	var cache any = this.Positions
	var arg map[string]any = ccxt.SafeMapTyped(message, "arg")
	var channelName *string = this.SafeString(arg, "channel")
	var data []any = ccxt.SafeListTyped(message, "data")
	var newPositions []any = []any{}
	for i := 0; i < len(data); i++ {
		var position any = this.ParseWsPosition(this.SafeValue(data, i))
		newPositions = append(newPositions, position)
		cache.(ccxt.Appender).Append(position)
		if channelName != nil {
			client.(ccxt.ClientInterface).Resolve(position, *channelName+":"+*this.SafeString(position, "symbol", ""))
		}
	}
}
func (this *Blofin) ParseWsPosition(position any, optionalArgs ...any) any {
	var market map[string]any = ccxt.GetArgMap(optionalArgs, 0, nil)
	_ = market
	return ccxt.PositionToMap(this.ParsePosition(position, market))
}

