func (this *Blofin) WatchMultipleWrapperAsync(isPublic bool, channelName any, callerMethodName any, optionalArgs ...any) <-chan ccxt.AsyncResult[any] {
	ch := make(chan ccxt.AsyncResult[any], 1)
	go this.watchMultipleWrapperBody(ch, isPublic, channelName, callerMethodName, optionalArgs...)
	return ch
}
func (this *Blofin) watchMultipleWrapperBody(ch chan ccxt.AsyncResult[any], isPublic bool, channelName any, callerMethodName any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// underlier method for all watch-multiple symbols
	symbolsArray := ccxt.GetArg(optionalArgs, 0, nil)
	_ = symbolsArray
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var callerMethodNameOptionPtr *string = nil
	callerMethodNameOptionPtr, paramsCallerMethodName := this.HandleParamString(params, "callerMethodName", callerMethodName)
	callerMethodNameOption := func() any {
		if callerMethodNameOptionPtr != nil {
			return *callerMethodNameOptionPtr
		}
		return nil
	}()
	// if ccxt.OHLCV method are being called, then symbols would be symbolsAndTimeframes (multi-dimensional) array
	var isOHLCV bool = (ccxt.IsEqual(channelName, "candle"))
	var symbolsRaw any = func() any {
		if isOHLCV {
			return this.GetListFromObjectValues(symbolsArray, 0)
		}
		return symbolsArray
	}()
	var symbols []string = this.MarketSymbols(symbolsRaw, nil, true, true)
	var firstMarket map[string]any = nil
	var firstSymbol *string = this.SafeString(symbols, 0)
	if firstSymbol != nil {
		firstMarket = this.Market(firstSymbol)
	}
	marketType, paramsMarketType := this.HandleMarketTypeAndParams(callerMethodNameOption, firstMarket, paramsCallerMethodName)
	if marketType == nil || *marketType != "swap" {
		panic(ccxt.NotSupported(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(this.Id+" ", callerMethodNameOption), "() does not support "), marketType), " markets yet")))
	}
	var rawSubscriptions []any = []any{}
	var messageHashes []any = []any{}
	if (symbols != nil) && (len(symbols) > 0) {
		for i := 0; i < len(symbols); i++ {
			var current string = symbols[i]
			var market map[string]any = nil
			var channel any = channelName
			if isOHLCV {
				market = this.Market(current)
				var tf *string = this.SafeString(this.SafeValue(symbolsArray, i), 1)
				var interval *string = this.SafeString(this.Timeframes, tf, tf)
				channel = ccxt.Add(channel, interval)
			} else {
				market = this.Market(current)
			}
			var topic map[string]any = map[string]any{
				"channel": channel,
				"instId":  market["id"],
			}
			rawSubscriptions = append(rawSubscriptions, topic)
			messageHashes = append(messageHashes, ccxt.Add(ccxt.Add(channel, ":"), this.SafeString(market, "symbol", "")))
		}
	} else {
		rawSubscriptions = append(rawSubscriptions, map[string]any{
			"channel": channelName,
		})
		messageHashes = append(messageHashes, channelName)
	}
	// private channel are difference, they only need plural channel name for multiple symbols
	if this.InArray(channelName, []any{"orders", "orders-algo", "positions"}) {
		rawSubscriptions = []any{map[string]any{
			"channel": channelName,
		}}
	}
	var request map[string]any = this.GetSubscriptionRequest(rawSubscriptions)
	var privateOrPublic string = "private"
	if isPublic == true {
		privateOrPublic = "public"
	}
	var typeUrls map[string]any = ccxt.SafeMapTyped(this.UrlsApi["ws"], marketType)
	var url *string = this.SafeString(typeUrls, privateOrPublic)

	r1 := <-this.WatchMultiple(url, messageHashes, this.DeepExtend(request, paramsMarketType), messageHashes)
	if r1.Err != nil {
		panic(r1.Err)
	}
	ch <- ccxt.AsyncResult[any]{Value: r1.Value}
	return nil
}
func (this *Blofin) UnsubscribeMultipleWrapperAsync(channelName string, callerMethodName string, symbolsArray any, optionalArgs ...any) <-chan ccxt.AsyncResult[any] {
	ch := make(chan ccxt.AsyncResult[any], 1)
	go this.unsubscribeMultipleWrapperBody(ch, channelName, callerMethodName, symbolsArray, optionalArgs...)
	return ch
}
func (this *Blofin) unsubscribeMultipleWrapperBody(ch chan ccxt.AsyncResult[any], channelName string, callerMethodName string, symbolsArray any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// underlier method for the public unWatch* methods, sends the same topics as watchMultipleWrapper
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var callerMethodNameOptionPtr *string = nil
	callerMethodNameOptionPtr, paramsCallerMethodName := this.HandleParamString(params, "callerMethodName", callerMethodName)
	callerMethodNameOption := func() any {
		if callerMethodNameOptionPtr != nil {
			return *callerMethodNameOptionPtr
		}
		return nil
	}()
	var isOHLCV bool = (channelName == "candle")
	var symbols any = []any{}
	if isOHLCV {
		symbols = this.MarketSymbols(this.GetListFromObjectValues(symbolsArray, 0), nil, false, true)
	} else {
		symbols = this.MarketSymbols(symbolsArray, nil, false, true)
	}
	var firstMarket map[string]any = this.Market(this.SafeString(symbols, 0))
	marketType, paramsMarketType := this.HandleMarketTypeAndParams(callerMethodNameOption, firstMarket, paramsCallerMethodName)
	if marketType == nil || *marketType != "swap" {
		panic(ccxt.NotSupported(ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add(this.Id+" ", callerMethodNameOption), "() does not support "), marketType), " markets yet")))
	}
	var topics []any = []any{}
	var messageHashes []any = []any{}
	for i := 0; i < ccxt.GetArrayLength(symbols); i++ {
		var market map[string]any = this.Market(this.SafeString(symbols, i))
		var channel any = channelName
		if isOHLCV {
			var tfArray any = ccxt.GetValue(symbolsArray, i)
			var tf any = ccxt.GetValue(tfArray, 1)
			var interval *string = this.SafeString(this.Timeframes, tf, tf)
			channel = ccxt.Add(channel, interval)
		}
		var topic map[string]any = map[string]any{
			"channel": channel,
			"instId":  market["id"],
		}
		topics = append(topics, topic)
		messageHashes = append(messageHashes, ccxt.Add(ccxt.Add(ccxt.Add("unsubscribe:", channel), ":"), market["symbol"]))
	}
	var request map[string]any = map[string]any{
		"op":   "unsubscribe",
		"args": topics,
	}
	var url any = ccxt.GetValue(ccxt.GetValue(ccxt.GetValue((this.Urls["api"]), "ws"), marketType), "public")

	r1 := <-this.WatchMultiple(url, messageHashes, this.DeepExtend(request, paramsMarketType), messageHashes)
	if r1.Err != nil {
		panic(r1.Err)
	}
	ch <- ccxt.AsyncResult[any]{Value: r1.Value}
	return nil
}
func (this *Blofin) HandleUnsubscription(client any, message any) {
	//
	//     {
	//         "event": "unsubscribe",
	//         "arg": {
	//             "channel": "candle1m",
	//             "instId": "BTC-USDT"
	//         }
	//     }
	//
	var arg map[string]any = ccxt.SafeMapTyped(message, "arg")
	var channel *string = this.SafeString(arg, "channel", "")
	var marketId *string = this.SafeString(arg, "instId")
	var market map[string]any = this.SafeMarket(marketId)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var subMessageHash string = *channel + ":" + *symbol
	if channel != nil && *channel == "trades" {
		this.CleanCache(map[string]any{
			"topic":   "trades",
			"symbols": []any{symbol},
		})
		this.CleanUnsubscription(ccxt.AsClient(client), subMessageHash, "unsubscribe:"+subMessageHash)
	} else if strings.HasPrefix(*channel, "candle") {
		var timeframe *string = this.FindTimeframe(strings.Replace(*channel, "candle", "", 1))
		if timeframe != nil {
			this.CleanCache(map[string]any{
				"topic":                "ohlcv",
				"symbolsAndTimeframes": []any{[]any{symbol, timeframe}},
			})
		}
		this.CleanUnsubscription(ccxt.AsClient(client), subMessageHash, "unsubscribe:"+subMessageHash)
	}
}
func (this *Blofin) GetSubscriptionRequest(args []any) map[string]any {
	return map[string]any{
		"op":   "subscribe",
		"args": args,
	}
}
func (this *Blofin) HandleMessage(client any, message any) {
	//
	// message examples
	//
	// {
	//   arg: {
	//     channel: "trades",
	//     instId: "DOGE-USDT",
	//   },
	//   event: "subscribe"
	// }
	//
	// incoming data updates' examples can be seen under each handler method
	//
	var methods map[string]any = map[string]any{
		"trades":       this.HandleTrades,
		"books":        this.HandleOrderBook,
		"tickers":      this.HandleTicker,
		"candle":       this.HandleOHLCV,
		"account":      this.HandleBalance,
		"orders":       this.HandleOrders,
		"orders-algo":  this.HandleOrders,
		"positions":    this.HandlePositions,
		"funding-rate": this.HandleFundingRate,
	}
	var method any = nil
	if ccxt.IsEqual(message, "pong") {
		client.(ccxt.ClientInterface).SetLastPong(this.Milliseconds())
		return
	} else {
		var event *string = this.SafeString(message, "event")
		if event != nil && *event == "subscribe" {
			return
		} else if event != nil && *event == "unsubscribe" {
			this.HandleUnsubscription(client, message)
			return
		} else if event != nil && *event == "login" {
			var future any = client.(ccxt.ClientInterface).FutureGet("authenticate_hash")
			future.(*ccxt.Future).Resolve(true)
			return
		} else if event != nil && *event == "error" {
			panic(ccxt.ExchangeError(this.Id + " error: " + this.Json(message)))
		}
		var arg map[string]any = ccxt.SafeMapTyped(message, "arg")
		var channelName *string = this.SafeString(arg, "channel")
		method = this.SafeValue(methods, channelName)
		if (ccxt.IsEqual(method, nil)) && (strings.Index(*channelName, "candle") >= 0) {
			method = methods["candle"]
		}
	}
	if !ccxt.IsEqual(method, nil) {
		ccxt.CallDynamically(method, client, message)
	}
}
func (this *Blofin) AuthenticateAsync(optionalArgs ...any) <-chan ccxt.AsyncResult[*string] {
	ch := make(chan ccxt.AsyncResult[*string], 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Blofin) authenticateBody(ch chan ccxt.AsyncResult[*string], optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.CheckRequiredCredentials()
	var milliseconds int64 = this.Milliseconds()
	var messageHash string = "authenticate_hash"
	var timestamp string = strconv.FormatInt(milliseconds, 10)
	var nonce string = "n_" + timestamp
	var auth string = "/users/self/verify" + "GET" + timestamp + "" + nonce
	var signature string = this.StringToBase64(this.Hmac(this.Encode(auth), this.Encode(this.Secret), ccxt.Sha256))
	var request map[string]any = map[string]any{
		"op": "login",
		"args": []any{map[string]any{
			"apiKey":     this.ApiKey,
			"passphrase": this.Password,
			"timestamp":  timestamp,
			"nonce":      nonce,
			"sign":       signature,
		}},
	}
	var marketType string = "swap" // for now
	var typeUrls map[string]any = ccxt.SafeMapTyped(this.UrlsApi["ws"], marketType)
	var url *string = this.SafeString(typeUrls, "private")

	r := <-this.Watch(url, messageHash, this.DeepExtend(request, params), messageHash)
	if r.Err != nil {
		panic(r.Err)
	}
	return nil
}

func NewBlofin(userConfig map[string]any) *Blofin {
	p := newBlofin()
	p.Init(userConfig)
	return p
}

func (this *Blofin) Init(userConfig map[string]any) {
	this.base.Init(this.DeepExtend(this.Describe(), userConfig))
	this.Itf = this
	this.Exchange.DerivedExchange = this
}

